package org.apache.commons.cli;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import org.junit.jupiter.params.provider.Arguments;

import java.lang.reflect.Method;
import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.*;

public class PatternOptionBuilderTest {

    private static Method getValueTypeMethod() throws Exception {
        Method m = PatternOptionBuilder.class.getDeclaredMethod("getValueType", char.class);
        m.setAccessible(true);
        return m;
    }

    static Stream<Arguments> valueTypeProvider() {
        return Stream.of(
            Arguments.of('@', PatternOptionBuilder.OBJECT_VALUE),
            Arguments.of(':', PatternOptionBuilder.STRING_VALUE),
            Arguments.of('%', PatternOptionBuilder.NUMBER_VALUE),
            Arguments.of('+', PatternOptionBuilder.CLASS_VALUE),
            Arguments.of('#', PatternOptionBuilder.DATE_VALUE),
            Arguments.of('<', PatternOptionBuilder.EXISTING_FILE_VALUE),
            Arguments.of('>', PatternOptionBuilder.FILE_VALUE),
            Arguments.of('*', PatternOptionBuilder.FILES_VALUE),
            Arguments.of('/', PatternOptionBuilder.URL_VALUE)
        );
    }

    @ParameterizedTest
    @MethodSource("valueTypeProvider")
    void testKnownValueCodes(char input, Class<?> expected) throws Exception {
        Method m = getValueTypeMethod();
        Object result = m.invoke(null, input);
        assertSame(expected, result);
    }

    @Test
    void testUnknownValueCodeReturnsNull() throws Exception {
        Method m = getValueTypeMethod();
        Object res = m.invoke(null, 'x');
        assertNull(res);

        // also test a control character
        res = m.invoke(null, '\u0000');
        assertNull(res);
    }

    @Test
    void testAllBranchesVisited() throws Exception {
        Method m = getValueTypeMethod();
        char[] codes = new char[]{'@', ':', '%', '+', '#', '<', '>', '*', '/'};
        for (char c : codes) {
            Object r = m.invoke(null, c);
            assertNotNull(r, "Expected non-null for code: " + c);
        }
    }
}

